/**
 * The Editor's Office sign-in panel.
 *
 * Two-step dossier flow, like the onboarding interview:
 *
 *   I.   The Email  — the writer types their address.
 *   II.  The Key    — passkey or one-time code. The passkey is the default
 *                     when the account already has one; OTP is sent
 *                     automatically on first-time sign-up and on every
 *                     sign-in for accounts that haven't set up a passkey.
 *
 * Bluesky sign-in sits in step 1 as a tertiary option — it carries its own
 * handle, so it doesn't need the email step.
 */
const normalizeEmail = (email: string) => email.trim().toLowerCase();
const looksLikeEmail = (email: string) =>
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());

export const AuthPanel = component$(() => {
  const auth = useAuth();

  const store = useStore({
    step: 1 as 1 | 2,
    /** "signin" for returning visitors (default), "signup" for new accounts. */
    mode: "signin" as "signin" | "signup",
    email: "",
    /** ATProto identifier, such as a Bluesky handle, DID, or PDS URL. */
    bskyHandle: "",
    /** Which key the user is on. `null` means "decide based on memory". */
    chosen: null as SignInMethod | null,
    /**
     * Whether this email/device is known to have a passkey (from the local
     * preference). We can't list a stranger's passkeys before a session
     * exists, so this preference is the only safe pre-sign-in signal — we use
     * it to decide whether to offer passkey sign-in at all.
     */
    knownPasskey: false,
    /** Whether we've already sent an OTP for this email in this session. */
    otpSent: false,
    /** Normalized email address that the current OTP belongs to. */
    otpSentFor: "",
    otpCode: "",
    sendingOtp: false,
    verifyingOtp: false,
    usingPasskey: false,
    usingBluesky: false,
    /** Once we've completed sign-in, surface a one-time prompt to add a passkey. */
    offerPasskey: false,
    addingPasskey: false,
    /** Confirmation shown after a passkey is registered from the signed-in view. */
    passkeyToast: null as string | null,
    error: null as AppError | string | null,
  });

  const sendOtp = $(async (email: string) => {
    const normalized = normalizeEmail(email);
    store.sendingOtp = true;
    store.error = null;
    try {
      const result = await emailOtp.sendVerificationOtp({
        email: normalized,
        type: "sign-in",
      });
      if (result?.error) {
        reportApplicationDiagnostic("twyne:auth:send-otp", result.error, {
          operation: "send-otp",
        });
        store.error = normalizeApplicationError(result.error, {
          source: "auth",
          metadata: { operation: "send-otp" },
        });
        return false;
      }
      store.otpSent = true;
      store.otpSentFor = normalized;
      return true;
    } catch (error) {
      reportApplicationDiagnostic("twyne:auth:send-otp", error, {
        operation: "send-otp",
      });
      store.error = normalizeApplicationError(error, {
        source: "auth",
        metadata: { operation: "send-otp" },
      });
      return false;
    } finally {
      store.sendingOtp = false;
    }
  });

  const handleStepOne = $(async () => {
    const trimmed = normalizeEmail(store.email);
    if (!looksLikeEmail(trimmed)) {
      store.error = "Add an email address so we know where to send the code.";
      return;
    }
    store.email = trimmed;
    store.error = null;
    // Look up the per-email preference. Passkey is the default only for
    // accounts known (on this device) to have one; everyone else gets OTP.
    const remembered = getPreferredMethod(trimmed);
    store.knownPasskey = remembered === "passkey";
    store.chosen = remembered ?? "otp";
    store.otpCode = "";
    store.offerPasskey = false;
