/** Return the locally-known PDS publication state for a folio, if any. */
export async function loadPublishedDocument(
  folioId: string,
): Promise<PublishResult | null> {
  const doc = await loadMetaFromIdb<DocumentRef>(docMetaKey(folioId));
  const publication =
    await loadMetaFromIdb<PublicationRef>(PUBLICATION_META_KEY);
  if (!doc?.uri || !publication?.uri) return null;
  const documentParts = parseAtUri(doc.uri);
  const publicationParts = parseAtUri(publication.uri);
  if (
    !documentParts ||
    !publicationParts ||
    documentParts.did !== publicationParts.did
  ) {
    return null;
    if (wanted.has("rubric")) {
      const row = await ctx.db
        .query("rubricResults")
        .withIndex("by_userId_folioId", (q) =>
          q.eq("userId", userId).eq("folioId", folioId),
        )
        .first();
      bundle.rubric = row?.result ?? null;
    }
    if (wanted.has("suggestions")) {
      bundle.suggestions = await ctx.db
        .query("suggestions")
        .withIndex("by_userId_folioId", (q) =>
          q.eq("userId", userId).eq("folioId", folioId),
        )
        .collect();
    }
    if (wanted.has("citations")) {
      const row = await ctx.db
        .query("bibliographies")
        .withIndex("by_userId", (q) => q.eq("userId", userId))
        .first();
      bundle.citations = (row?.entries ?? []).filter(
        (entry: { folioId?: unknown }) =>
          !entry?.folioId || entry.folioId === folioId,
      );
      }
    }
    return next;
  },
});

